from html import escape as E

def boxes(labels):
 w=760/len(labels)
 return ''.join(f'<rect x="{10+i*w}" y="42" width="{w-12}" height="68" rx="8" fill="#e2eaf0"/><text x="{10+i*w+(w-12)/2}" y="82" text-anchor="middle">{E(t)}</text>' for i,t in enumerate(labels))
def figure(n):
 captions={1:'Compatible intervals A and C touch at time 3; B overlaps both.',2:'Exact operation counts grow toward the quadratic doubling ratio.',3:'The triangular loop visits 1 + 2 + 3 + 4 = 10 positions.',4:'Front insertion shifts existing array values; the linked-list head changes by a link.',5:'Five hash slots after linear probing: 10, 15 and 20 share the same initial hash.',6:'A min-heap after inserting 1. Every parent is at most its children.',7:'Merge two sorted runs by repeatedly taking the smaller front value.',8:'Stable digit passes preserve the ordering built by the previous pass.',9:'BFS levels from vertex 1. Both 2 and 3 can reach vertex 4.',10:'Kruskal chooses AB and BC, joining all vertices with total weight 3.',11:'The route through B improves the tentative distance to C from 5 to 3.',12:'Each Fibonacci table entry uses the preceding two entries.',13:'Edit-distance table: row prefixes of cat, column prefixes of cut.',14:'Reduction direction: an instance of A becomes an instance of X; a solver for X answers A.'}
 if n==1:
  inner=''.join(f'<line x1="{70+a*100}" y1="{45+i*50}" x2="{70+b*100}" y2="{45+i*50}" style="stroke:{c};stroke-width:10"/><text x="20" y="{51+i*50}">{name}</text>' for i,(name,a,b,c) in enumerate([('A',0,3,'#26735d'),('B',2,4,'#ac4939'),('C',3,5,'#26735d')]))+''.join(f'<text x="{70+i*100}" y="190">{i}</text>' for i in range(6))
 elif n==3:
  inner=''.join(f'<circle cx="{180+j*55}" cy="{30+i*45}" r="12" fill="#39725e"/>' for i in range(4) for j in range(i+1))
 elif n in (6,9,10,11):
  nodes,edges=({6:({'1':(370,35),'2':(230,100),'3':(510,100),'4':(150,170)},[('1','2',''),('1','3',''),('2','4','')]),9:({'1':(90,100),'2':(280,45),'3':(280,155),'4':(470,100),'5':(660,100)},[('1','2',''),('1','3',''),('2','4',''),('3','4',''),('4','5','')]),10:({'A':(130,160),'B':(370,35),'C':(610,160)},[('A','B','1'),('B','C','2'),('A','C','3')]),11:({'A':(130,160),'B':(370,35),'C':(610,160)},[('A','B','2 →'),('B','C','1 →'),('A','C','5 →')])})[n]
  inner=''.join(f'<line x1="{nodes[a][0]}" y1="{nodes[a][1]}" x2="{nodes[b][0]}" y2="{nodes[b][1]}"/><text x="{(nodes[a][0]+nodes[b][0])/2}" y="{(nodes[a][1]+nodes[b][1])/2-12}" text-anchor="middle">{label}</text>' for a,b,label in edges)
  inner+=''.join(f'<circle cx="{x}" cy="{y}" r="21" fill="#d4e4dc"/><text x="{x}" y="{y+6}" text-anchor="middle">{label}</text>' for label,(x,y) in nodes.items())
 elif n==13:
  rows=[['','∅','c','u','t'],['∅','0','1','2','3'],['c','1','0','1','2'],['a','2','1','1','2'],['t','3','2','2','1']]
  inner=''.join(f'<text x="{240+j*65}" y="{25+i*40}" text-anchor="middle">{t}</text>' for i,row in enumerate(rows) for j,t in enumerate(row))
 else:
  labels={2:['n=10: 400','n=20: 1400','n=40: 5200'],4:['before: 2, 5, 7','shift right →','after: 8, 2, 5, 7'],5:['0: 10','1: 15','2: 20','3: 3','4: empty'],7:['1,4,7 + 2,3,8','choose smaller front','1,2,3,4,7,8'],8:['21,13,12,23','21,12,13,23','12,13,21,23'],12:['F0=0','F1=1','F2=1','F3=2','F4=3','F5=5','F6=8'],14:['Problem A','transform → X','solve X → answer A']}[n]
  inner=boxes(labels)
 return f'<figure><svg viewBox="0 0 780 220" role="img" aria-label="{E(captions[n])}">{inner}</svg><figcaption>{E(captions[n])}</figcaption></figure>'

